"""Monthly report helpers: per-category totals and duplicate detection."""

from datetime import date


def _parse_month(month):
    """Parse "YYYY-MM" into (year, month), raising ValueError if malformed."""
    try:
        year_s, month_s = month.split("-")
        if len(year_s) != 4 or len(month_s) != 2:
            raise ValueError
        year, mon = int(year_s), int(month_s)
        date(year, mon, 1)  # validates range
    except (ValueError, AttributeError):
        raise ValueError(f"invalid month {month!r}; expected YYYY-MM") from None
    return year, mon


def _cents(amount):
    return int(round(amount * 100))


def in_month(transactions, month):
    """Return the transactions dated within the calendar month "YYYY-MM"."""
    year, mon = _parse_month(month)
    return [t for t in transactions if t.day.year == year and t.day.month == mon]


def summarize(transactions, month):
    """Map category -> net total (2 decimals) for the month, omitting zero totals."""
    totals = {}
    for t in in_month(transactions, month):
        totals[t.category] = totals.get(t.category, 0) + _cents(t.amount)
    return {cat: round(c / 100, 2) for cat, c in totals.items() if c != 0}


def find_duplicates(transactions):
    """Return (earlier_id, later_id) pairs with same payee and amount within 2 days.

    Refunds (negative amounts) are never duplicates. Sorted by the earlier
    transaction's date, then its id.
    """
    candidates = sorted(
        (t for t in transactions if t.amount > 0),
        key=lambda t: (t.day, t.id),
    )
    found = []
    for i, a in enumerate(candidates):
        for b in candidates[i + 1:]:
            if (b.day - a.day).days > 2:
                break
            if b.payee == a.payee and _cents(b.amount) == _cents(a.amount):
                found.append((a, b))
    found.sort(key=lambda p: (p[0].day, p[0].id, p[1].day, p[1].id))
    return [(a.id, b.id) for a, b in found]
